CREATE DATABASE IF NOT EXISTS hive CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE hive;
SET GLOBAL max_allowed_packet = 67108864;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, username VARCHAR(32) NOT NULL UNIQUE, display_name VARCHAR(80) NOT NULL, password_hash VARCHAR(255) NOT NULL, avatar LONGTEXT NULL, online TINYINT(1) NOT NULL DEFAULT 0, typing_until DATETIME NULL, last_seen DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE conversations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_one INT UNSIGNED NOT NULL, user_two INT UNSIGNED NOT NULL, UNIQUE KEY pair_key(user_one,user_two), FOREIGN KEY(user_one) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(user_two) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, conversation_id INT UNSIGNED NOT NULL, sender_id INT UNSIGNED NOT NULL, body TEXT NOT NULL, seen_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(conversation_id) REFERENCES conversations(id) ON DELETE CASCADE, FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE `groups` (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, owner_id INT UNSIGNED NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(owner_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE group_members (group_id INT UNSIGNED NOT NULL, user_id INT UNSIGNED NOT NULL, joined_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(group_id,user_id), FOREIGN KEY(group_id) REFERENCES `groups`(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE group_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, group_id INT UNSIGNED NOT NULL, sender_id INT UNSIGNED NOT NULL, body TEXT NOT NULL, seen_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(group_id) REFERENCES `groups`(id) ON DELETE CASCADE, FOREIGN KEY(sender_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
